function writeAll(out: Writable, lines: string[], done: () => void) {
  let i = 0
  const next = () => {
    while (i < lines.length) {
      if (!out.write(lines[i++] + '\n')) return out.once('drain', next)
    }
    done()
  }
  next()
}

const lines = new Transform({
  readableObjectMode: true,
  transform(chunk, _enc, cb) {
    this.tail = (this.tail ?? '') + chunk
    const parts = this.tail.split('\n')
    this.tail = parts.pop()
    for (const p of parts) this.push(p)
    cb()
  },
  flush(cb) { if (this.tail) this.push(this.tail); cb() },
})

